package com.troday.api.service;

import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.LocalDateTime; import java.util.*;

@Service public class AdminService {
 @org.springframework.beans.factory.annotation.Autowired private DomainSupport domain;
 private final AccountService accounts; private final ReviewRepository reviews; private final ReportRepository reports; private final ContractTemplateRepository templates; private final ModerationActionRepository actions; private final UserRepository users; private final RoomTenantRepository tenants;
 public AdminService(AccountService a,ReviewRepository r,ReportRepository reports,ContractTemplateRepository t,ModerationActionRepository actions,UserRepository u,RoomTenantRepository tenants){accounts=a;reviews=r;this.reports=reports;templates=t;this.actions=actions;users=u;this.tenants=tenants;}
 public ApiResponseDto<?> publicReviews(Long roomId){return ok("GET",reviews.findByRoomIdAndStatus(roomId,"PUBLISHED").stream().map(this::reviewData).toList());}
 @Transactional public ApiResponseDto<?> createReview(HttpServletRequest r,JsonNode b){Long me=accounts.authenticatedUserId(r);require(b);Long cid=required(b,"contractId"),rid=required(b,"roomId"),tid=required(b,"roomTenantId");RoomTenant rt=tenants.findById(tid).orElseThrow(()->notFound("Không tìm thấy lượt cư trú"));if(!Set.of("ACTIVE","LEFT").contains(rt.getStatus())||!Objects.equals(rt.getTenantId(),me)||!Objects.equals(rt.getContractId(),cid)||!Objects.equals(rt.getRoomId(),rid))throw forbidden("Chỉ người đã cư trú mới được đánh giá");if(reviews.existsByReviewerIdAndRoomIdAndContractId(me,rid,cid))throw conflict("Bạn đã đánh giá lượt cư trú này");int rating=b.get("rating").asInt();if(rating<1||rating>5)throw bad("rating phải từ 1 đến 5");Review x=new Review();x.setReviewerId(me);x.setRoomId(rid);x.setContractId(cid);x.setRoomTenantId(tid);x.setRating(rating);x.setContent(text(b,"content"));return ok("POST",reviewData(reviews.save(x)));}
 @Transactional public ApiResponseDto<?> moderateReview(HttpServletRequest r,Long id,JsonNode b){Long admin=accounts.requireAdminId(r);Review x=reviews.findById(id).orElseThrow(()->notFound("Không tìm thấy đánh giá"));String d=text(b,"decision");if(!Set.of("HIDE","RESTORE","DELETE").contains(d))throw bad("decision không hợp lệ");String before=x.getStatus();x.setStatus("HIDE".equals(d)?"HIDDEN":"RESTORE".equals(d)?"PUBLISHED":"DELETED");x.setHiddenById(admin);x.setHiddenReason(text(b,"reason"));x.setHiddenAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));reviews.save(x);log(admin,"REVIEW_"+d,x.getReviewerId(),null,null,before,x.getStatus(),text(b,"reason"));return ok("POST",reviewData(x));}
 @Transactional public ApiResponseDto<?> createReport(HttpServletRequest r,JsonNode b){Long me=accounts.authenticatedUserId(r);require(b);if(b.hasNonNull("targetType")&&b.hasNonNull("targetId")){String key=switch(text(b,"targetType")){case "POST"->"reportedPostId";case "USER"->"reportedUserId";case "CONTRACT"->"contractId";case "ROOMMATE_REQUEST"->"roommateRequestId";default->throw bad("targetType không hợp lệ");};((com.fasterxml.jackson.databind.node.ObjectNode)b).set(key,b.get("targetId"));}
        if(b.hasNonNull("reportedPostId")&&!domain.publicPost(required(b,"reportedPostId")))throw forbidden("Không được đọc đối tượng báo cáo");if(b.hasNonNull("contractId")&&!domain.contractReader(required(b,"contractId"),me))throw forbidden("Không thuộc hợp đồng");if(b.hasNonNull("roommateRequestId")&&!domain.exists("SELECT id FROM roommate_requests WHERE id=? AND (sender_id=? OR receiver_id=?)",required(b,"roommateRequestId"),me,me))throw forbidden("Không thuộc kết nối");int targets=(b.hasNonNull("reportedUserId")?1:0)+(b.hasNonNull("reportedPostId")?1:0)+(b.hasNonNull("contractId")?1:0)+(b.hasNonNull("roommateRequestId")?1:0);if(targets!=1)throw bad("Phải có đúng một đối tượng báo cáo");Report x=new Report();x.setReporterId(me);x.setType("POST".equals(text(b,"type"))?"VIOLATION":text(b,"type"));x.setReportedUserId(longValue(b,"reportedUserId"));x.setReportedPostId(longValue(b,"reportedPostId"));x.setContractId(longValue(b,"contractId"));x.setRoommateRequestId(longValue(b,"roommateRequestId"));x.setReason(text(b,"reason"));if(x.getReason().isBlank())throw bad("reason là bắt buộc");x=reports.saveAndFlush(x);if(b.has("evidenceFileIds"))for(JsonNode fid:b.get("evidenceFileIds")){domain.activeFile(fid.asLong(),me,"REPORT_EVIDENCE");if(domain.jdbc.update("UPDATE files SET report_id=? WHERE id=? AND report_id IS NULL",x.getId(),fid.asLong())!=1)throw conflict("Minh chứng đã liên kết báo cáo khác");}return ok("POST",reportData(x,false));}
 public ApiResponseDto<?> myReports(HttpServletRequest r){
Long me=accounts.authenticatedUserId(r);return ok("GET",domain.page(r,"FROM reports p WHERE p.reporter_id=?","p.id","p.reason","p.id DESC",List.of(me),Map.of("status","p.status","type","p.type"),id->reportData(reports.findById(id).orElseThrow(),false)));
 }
 public ApiResponseDto<?> adminReports(HttpServletRequest r){
accounts.requireAdminId(r);return ok("GET",domain.page(r,"FROM reports p WHERE 1=1","p.id","p.reason","p.id DESC",List.of(),Map.of("status","p.status","type","p.type"),id->reportData(reports.findById(id).orElseThrow(),true)));
 }
 public ApiResponseDto<?> adminReport(HttpServletRequest r,Long id){accounts.requireAdminId(r);return ok("GET",reportData(report(id),true));}
 @Transactional public ApiResponseDto<?> reportDecision(HttpServletRequest r,Long id,JsonNode b){Long admin=accounts.requireAdminId(r);Report x=report(id);if(Set.of("RESOLVED","DISMISSED").contains(x.getStatus()))throw conflict("Báo cáo đã đóng");String previous=x.getStatus();String d=text(b,"decision");if(!Set.of("INVESTIGATE","RESOLVE","DISMISS").contains(d))throw bad("decision không hợp lệ");x.setStatus("INVESTIGATE".equals(d)?"INVESTIGATING":"RESOLVE".equals(d)?"RESOLVED":"DISMISSED");x.setResolution(text(b,"resolution"));if(Set.of("RESOLVED","DISMISSED").contains(x.getStatus())&&x.getResolution().isBlank())throw bad("resolution là bắt buộc");x.setHandledById(admin);x.setHandledAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));Report saved=reports.save(x);log(admin,"REPORT_"+d,null,null,id,previous,saved.getStatus(),x.getResolution());return ok("POST",reportData(saved,true));}
 public ApiResponseDto<?> users(HttpServletRequest r){
accounts.requireAdminId(r);return ok("GET",domain.page(r,"FROM users u WHERE 1=1","u.id","CONCAT_WS(' ',u.full_name,u.email,u.phone_number)","u.id DESC",List.of(),Map.of("status","u.status","role","u.role"),id->userData(users.findById(id).orElseThrow())));
 } public ApiResponseDto<?> user(HttpServletRequest r,Long id){accounts.requireAdminId(r);return ok("GET",userData(user(id)));}
 @Transactional public ApiResponseDto<?> lock(HttpServletRequest r,Long id,JsonNode b){Long admin=accounts.requireAdminId(r);User u=user(id);if(!"ACTIVE".equals(u.getStatus()))throw conflict("Tài khoản không ở trạng thái ACTIVE");if(text(b,"reason").isBlank())throw bad("Cần lý do khóa tài khoản");if(admin.equals(id))throw bad("Không được tự khóa tài khoản");u.setStatus("LOCKED");domain.jdbc.update("UPDATE auth_sessions SET revoked_at=UTC_TIMESTAMP(6),revocation_reason='ACCOUNT_LOCKED' WHERE user_id=? AND revoked_at IS NULL",id);u.setLockedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));u.setLockedById(admin);u.setLockReason(text(b,"reason"));User saved=users.save(u);log(admin,"USER_LOCK",id,null,null,"ACTIVE","LOCKED",u.getLockReason());return ok("POST",userData(saved));}
 @Transactional public ApiResponseDto<?> unlock(HttpServletRequest r,Long id){Long admin=accounts.requireAdminId(r);User u=user(id);if(!"LOCKED".equals(u.getStatus()))throw conflict("Tài khoản không bị khóa");u.setStatus("ACTIVE");u.setLockedAt(null);u.setLockedById(admin);u.setLockReason(null);User saved=users.save(u);log(admin,"USER_UNLOCK",id,null,null,"LOCKED","ACTIVE","Mở khóa tài khoản");return ok("POST",userData(saved));}
 public ApiResponseDto<?> templateList(HttpServletRequest r){accounts.authenticatedUserId(r);return ok("GET",(domain.exists("SELECT id FROM admins WHERE id=?",accounts.authenticatedUserId(r))?templates.findAll():templates.findByActiveTrueOrderByNameAscVersionDesc()).stream().map(this::templateData).toList());}
 @Transactional public ApiResponseDto<?> templateCreate(HttpServletRequest r,JsonNode b){Long admin=accounts.requireAdminId(r);require(b);String name=text(b,"name");ContractTemplate x=new ContractTemplate();x.setCreatedById(admin);x.setName(name);x.setContent(text(b,"content"));x.setVersion(templates.findTopByNameOrderByVersionDesc(name).map(y->y.getVersion()+1).orElse(1));x.setActive(true);return ok("POST",templateData(templates.save(x)));}
 @Transactional public ApiResponseDto<?> templateUpdate(HttpServletRequest r,Long id,JsonNode b){accounts.requireAdminId(r);ContractTemplate x=templates.findById(id).orElseThrow(()->notFound("Không tìm thấy mẫu hợp đồng"));if(b.has("active"))x.setActive(b.get("active").asBoolean());if(b.has("content")||b.has("name"))throw bad("Nội dung mới cần tạo phiên bản mẫu mới");return ok("PATCH",templateData(templates.save(x)));}
 public ApiResponseDto<?> actionList(HttpServletRequest r){
accounts.requireAdminId(r);return ok("GET",domain.page(r,"FROM moderation_actions a WHERE 1=1","a.id","CONCAT_WS(' ',a.action,a.reason)","a.occurred_at DESC,a.id DESC",List.of(),Map.of("action","a.action","actorUserId","a.actor_user_id","targetUserId","a.target_user_id","targetPostId","a.target_post_id"),id->actionData(actions.findById(id).orElseThrow())));
 } public ApiResponseDto<?> action(HttpServletRequest r,Long id){accounts.requireAdminId(r);return ok("GET",actionData(actions.findById(id).orElseThrow(()->notFound("Không tìm thấy nhật ký"))));}
 public ApiResponseDto<?> dashboard(HttpServletRequest r){
accounts.requireAdminId(r);return ok("GET",Map.of("pendingReportCount",reports.findByStatusOrderByIdAsc("PENDING").size(),"pendingPostCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM posts WHERE status='PENDING_REVIEW'",Long.class),"pendingIdentityCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM tenant_identity_verifications WHERE status='PENDING'",Long.class),"pendingLandlordCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM landlord_verifications WHERE status='PENDING'",Long.class),"pendingHouseCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM rental_house_verifications WHERE status='PENDING'",Long.class),"userCount",users.count()));
 }
 private void log(Long actor,String action,Long uid,Long pid,Long rid,String before,String after,String reason){ModerationAction x=new ModerationAction();x.setActorUserId(actor);x.setAction(action);x.setTargetUserId(uid);x.setTargetPostId(pid);x.setTargetReportId(rid);x.setBeforeSnapshot(domain.json(Map.of("status",Objects.toString(before,""))));x.setAfterSnapshot(domain.json(Map.of("status",Objects.toString(after,""))));x.setReason(reason==null||reason.isBlank()?"Không có lý do":reason);x.setOccurredAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));actions.save(x);}
 private Map<String,Object> reviewData(Review x){return Map.of("id",x.getId(),"roomId",x.getRoomId(),"rating",x.getRating(),"content",Objects.toString(x.getContent(),""),"status",x.getStatus(),"reviewerDisplayName","Người thuê");} private Map<String,Object> reportData(Report x,boolean admin){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("type",x.getType());m.put("status",x.getStatus());m.put("reason",x.getReason());m.put("resolution",Objects.toString(x.getResolution(),""));m.put("reporterId",x.getReporterId());m.put("createdAt",domain.jdbc.queryForObject("SELECT created_at FROM reports WHERE id=?",java.time.LocalDateTime.class,x.getId()));m.put("evidenceFileIds",domain.jdbc.queryForList("SELECT id FROM files WHERE report_id=?",Long.class,x.getId()));{m.put("reportedUserId",x.getReportedUserId());m.put("reportedPostId",x.getReportedPostId());m.put("contractId",x.getContractId());}return m;} private Map<String,Object> userData(User x){return Map.of("id",x.getId(),"fullName",x.getFullName(),"email",Objects.toString(x.getEmail(),""),"role",x.getRole(),"status",x.getStatus(),"lockReason",Objects.toString(x.getLockReason(),""));} private Map<String,Object> templateData(ContractTemplate x){return Map.of("id",x.getId(),"name",x.getName(),"version",x.getVersion(),"content",x.getContent(),"active",x.getActive());} private Map<String,Object> actionData(ModerationAction x){return Map.of("id",x.getId(),"actorUserId",x.getActorUserId(),"action",x.getAction(),"reason",x.getReason(),"beforeSnapshot",Objects.toString(x.getBeforeSnapshot(),""),"afterSnapshot",Objects.toString(x.getAfterSnapshot(),""),"occurredAt",x.getOccurredAt());}
 public void requireRoomReader(HttpServletRequest r,Long rid){domain.roomReader(rid,r.getHeader("Authorization")==null?null:accounts.authenticatedUserId(r));}
 private Report report(Long id){return reports.findById(id).orElseThrow(()->notFound("Không tìm thấy báo cáo"));} private User user(Long id){return users.findById(id).orElseThrow(()->notFound("Không tìm thấy tài khoản"));} private Long required(JsonNode b,String k){Long x=longValue(b,k);if(x==null)throw bad(k+" là bắt buộc");return x;} private Long longValue(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asLong():null;} private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";} private void require(JsonNode b){if(b==null||!b.isObject())throw bad("JSON request là bắt buộc");} private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);} private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,m);} private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);} private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
